content.text:
{
  "name": "Tron1 里程计桥接节点",
  "name_en": "Tron1 Odometry Bridge Node",
  "manufacturer": "limx",
  "description": "这是一个非实体的软件组件：ROS2 节点，用于把 Tron1 的 WebSocket 里程计数据转换并发布为 ROS2 的 /odom 话题消息，供机器人定位、导航与状态集成使用。",
  "description_en": "This is a non-physical software component: a ROS2 node that converts Tron1 odometry data from WebSocket into ROS2 /odom topic messages for robot localization, navigation, and system integration.",
  "actions": [
    {
      "action_name": "auto-on_open",
      "description": "在 WebSocket 连接建立后发送启用里程计数据流的请求。",
      "description_en": "Send a request to enable odometry streaming after the WebSocket connection is established."
    },
    {
      "action_name": "auto-on_message",
      "description": "接收 WebSocket 消息并处理收到的里程计相关数据。",
      "description_en": "Receive WebSocket messages and process incoming odometry-related data."
    },
    {
      "action_name": "auto-on_error",
      "description": "处理 WebSocket 通信过程中发生的错误。",
      "description_en": "Handle errors that occur during WebSocket communication."
    },
    {
      "action_name": "auto-on_close",
      "description": "处理 WebSocket 连接关闭事件。",
      "description_en": "Handle the WebSocket connection close event."
    },
    {
      "action_name": "auto-send_enable_odom",
      "description": "发送启用或禁用里程计数据流的请求。",
      "description_en": "Send a request to enable or disable odometry streaming."
    },
    {
      "action_name": "auto-handle_odom",
      "description": "将 WebSocket 里程计数据转换为 ROS2 Odometry 消息并发布。",
      "description_en": "Convert WebSocket odometry data into a ROS2 Odometry message and publish it."
    },
    {
      "action_name": "auto-websocket_loop",
      "description": "运行带重连机制的 WebSocket 主循环。",
      "description_en": "Run the main WebSocket loop with reconnection handling."
    },
    {
      "action_name": "auto-destroy_node",
      "description": "在节点关闭时禁用里程计数据流并清理资源。",
      "description_en": "Disable odometry streaming and clean up resources when the node shuts down."
    }
  ],
  "tag_hints": [
    "ROS2 odometry bridge",
    "WebSocket telemetry",
    "/odom publishing",
    "mobile robot localization",
    "Tron1 robot",
    "Odometry message conversion"
  ]
}

